    gsap.set(navbar, { yPercent: 0 });

    function onScroll() {
      const y = window.scrollY;
      const delta = y - lastY;

      // Toujours ré-afficher au tout début de page (rebond iOS etc.)
      if (y <= 0) {
        if (hidden) {
          gsap.to(navbar, { yPercent: 0, duration: 0.2, ease: SHOW_EASE, overwrite: 'auto' });
          hidden = false;
        }
        lastY = y;
        ticking = false;
        return;
      }

      // Seuil pour éviter l'effet sapin de Noël
      if (Math.abs(delta) > THRESHOLD) {
        if (delta > 0 && !hidden) {
          // on descend -> cacher
          gsap.to(navbar, {
            yPercent: -100,
            duration: 0.4,
            ease: HIDE_EASE,
            overwrite: 'auto'
          });
          hidden = true;
        } else if (delta < 0 && hidden) {
          // on remonte -> montrer
          gsap.to(navbar, { yPercent: 0, duration: 0.4, ease: SHOW_EASE, overwrite: 'auto' });
          hidden = false;
        }
        lastY = y;
      }

      ticking = false;
    }

